@Override // ru.jecklandin.stickman.generator.interpolator.IInterpolator
public List<Frame> interpolate(Frame frame1, Frame frame2, int duration, Scene targetScene) {
    int i = duration;
    LinkedList linkedList = new LinkedList();
    int indexOf = frame1.getScene().getIndexOf(frame1);
    float speedMod = targetScene.getSpeedMod(indexOf);
    Easing.EASING easing = Easing.EASING.NO;
    int i2 = 0;
    while (i2 < i) {
        Frame frame = new Frame(targetScene, -1);
        frame.mSpeedMod = speedMod;
        frame.mOriginFrameIndex = indexOf;
        Set<String> setExclude = exclude(frame1, frame2);
        for (Unit unit : frame1.getUnits()) {
            if (!setExclude.contains(unit.getName())) {
                Optional<Unit> optionalFindUnitByExactName = frame2.findUnitByExactName(unit.getName());
                if (optionalFindUnitByExactName.isPresent()) {
                    Unit unit2 = optionalFindUnitByExactName.get();
                    Unit unitInstance = unit.instance(frame);
                    int i3 = i2;
                    i2 = i3;
                    unitInstance.mState.set(UnitStateInterpolator.inbetween(frame1, frame2, unit, unit2, i3, i), true);
                    unitInstance.mState.setOwnUnit(unitInstance);
                    unitInstance.setName(unit.getName());
                    unitInstance.updateInternalState();
                    frame.addUnit(unitInstance);
                    i = duration;
                }
            }
        }
        try {
            adjustSlavesPositions(frame1, frame2, frame);
        } catch (Exception e) {
            e.printStackTrace();
        }
        frame.setBg(inbetweenBackgroundName(frame1));
        i = duration;
        frame.mBgMove.set(inbetweenBackground(frame1, frame2, i2, i, easing, 0.5f));
        frame.mCameraMove.set(inbetweenCamera(frame1, frame2, i2, i));
        linkedList.add(frame);
        i2++;
    }
    Frame frameClone = frame2.clone(targetScene);
    frameClone.mSpeedMod = speedMod;
    frameClone.mOriginFrameIndex = indexOf;
    linkedList.add(frameClone);
    Preconditions.checkState(linkedList.size() == i + 1);
    return linkedList;
}
